// Write uploaded photos to a local work dir and build the JSON payload
// incident_pack.py --json expects: plate, date, time, location, notes, photos: [paths]
const fs = require('fs');
const path = require('path');

const workDir = $env.NORTHERN_LIGHTS_WORKDIR || '/tmp/northern-lights-submissions';
const submissionId = Date.now().toString();
const dir = path.join(workDir, submissionId);
fs.mkdirSync(dir, { recursive: true });

const binaryKeys = Object.keys(items[0].binary || {});
const photoPaths = [];
for (const key of binaryKeys) {
  const bin = items[0].binary[key];
  const fname = bin.fileName || `${key}.jpg`;
  const outPath = path.join(dir, fname);
  fs.writeFileSync(outPath, Buffer.from(bin.data, 'base64'));
  photoPaths.push(outPath);
}

const payload = {
  plate: $json['Plate number'] || '',
  date: $json['Date'] || '',
  time: $json['Time'] || '',
  location: $json['Location'] || '',
  notes: $json['Notes'] || '',
  photos: photoPaths
};

const jsonPath = path.join(dir, 'submission.json');
fs.writeFileSync(jsonPath, JSON.stringify(payload, null, 2));

return [{ json: { jsonPath, dir } }];
